package dev.jdguo.bank.ledger;
import dev.jdguo.bank.currency.BankConfig;
import dev.jdguo.bank.market.NoteRegime;
import com.google.gson.JsonParser;
import java.math.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class WelcomeGiftTest {
 private static BankBooks books(){return BankBooks.create(BankConfig.defaults());}
 private static BigDecimal d(String s){return new BigDecimal(s);}
 private static void ok(TxResult r){assertTrue(r.success(), r.message());}
 private static boolean claimed(BankBooks b,UUID p){return b.welcomeGift(p,false).get("claimed").getAsBoolean();}
 private static void eq(String value,BigDecimal actual){assertEquals(0,d(value).compareTo(actual));}
 @Test void oldSaveDefaultsOffAndNoReceipt(){var b=books();var root=JsonParser.parseString(b.toJson()).getAsJsonObject();root.remove("welcomeGift");b=BankBooks.fromJson(root.toString(),BankConfig.defaults());var p=UUID.randomUUID();assertFalse(b.welcomeGift(p,false).get("enabled").getAsBoolean());assertEquals("disabled",b.claimWelcomeGift(p,0).code());assertFalse(claimed(b,p));}
 @Test void permissionValidationAndStaleSettingsDoNotMutate(){var b=books();var before=b.toJson();assertEquals("permission",b.configureWelcomeGift(false,0,true,"note",d("1")).code());assertEquals(before,b.toJson());for(var amount:List.of("0","-1","0.00001","10000000000000000000000000000"))assertFalse(b.configureWelcomeGift(true,0,true,"note",d(amount)).success());assertFalse(b.configureWelcomeGift(true,0,true,"diamond",d("0.5")).success());assertFalse(b.configureWelcomeGift(true,0,true,"missing",d("1")).success());assertEquals(before,b.toJson());ok(b.configureWelcomeGift(true,0,true,"note",d("1")));before=b.toJson();assertEquals("stale_config",b.configureWelcomeGift(true,0,false,"note",d("1")).code());assertEquals(before,b.toJson());}
 @Test void insufficientFundsDoesNotClaimAndCanRetry(){var b=books();var p=UUID.randomUUID();ok(b.configureWelcomeGift(true,0,true,"note",d("2.1234")));String before=b.toJson();assertFalse(b.claimWelcomeGift(p,1).success());assertEquals(before,b.toJson());assertFalse(claimed(b,p));b.creditUnbacked(p,"note",BigInteger.TEN);ok(b.claimWelcomeGift(p,1));eq("2.1234",b.balanceExact(p,"note"));eq("7.8766",b.treasuryExact("note"));assertTrue(claimed(b,p));}
 @Test void repeatedPacketsReopenAndRestartOnlyPayOnce(){var b=books();var p=UUID.randomUUID();b.creditUnbacked(p,"note",BigInteger.TEN);ok(b.configureWelcomeGift(true,0,true,"note",d("2")));ok(b.claimWelcomeGift(p,1));String after=b.toJson();for(int i=0;i<20;i++)assertEquals("already_claimed",b.claimWelcomeGift(p,1).code());assertEquals(after,b.toJson());b=BankBooks.fromJson(after,BankConfig.defaults());assertEquals("already_claimed",b.claimWelcomeGift(p,1).code());eq("2",b.balanceExact(p,"note"));}
 @Test void configChangesNeverResetAndBothOldNewPlayersEligible(){var b=books();var old=UUID.randomUUID();var fresh=UUID.randomUUID();b.deposit(old,"diamond",BigInteger.ONE);b.creditUnbacked(old,"note",BigInteger.TEN);ok(b.configureWelcomeGift(true,0,true,"note",d("1")));ok(b.claimWelcomeGift(old,1));ok(b.configureWelcomeGift(true,1,true,"note",d("2")));assertEquals("stale_config",b.claimWelcomeGift(fresh,1).code());ok(b.claimWelcomeGift(fresh,2));assertEquals("already_claimed",b.claimWelcomeGift(old,2).code());eq("1",b.balanceExact(old,"note"));eq("2",b.balanceExact(fresh,"note"));}
 @Test void legacyWriterDroppingConfigCannotEraseClaim(){var b=books();var p=UUID.randomUUID();b.creditUnbacked(p,"note",BigInteger.TEN);ok(b.configureWelcomeGift(true,0,true,"note",d("1")));ok(b.claimWelcomeGift(p,1));var root=JsonParser.parseString(b.toJson()).getAsJsonObject();root.remove("welcomeGift");b=BankBooks.fromJson(root.toString(),BankConfig.defaults());ok(b.configureWelcomeGift(true,0,true,"note",d("1")));assertEquals("already_claimed",b.claimWelcomeGift(p,1).code());eq("1",b.balanceExact(p,"note"));}
 @Test void personalGiftBuysRealInventoryAndFailureDoesNotClaim(){var b=books();var issuer=UUID.randomUUID();var p=UUID.randomUUID();assertTrue(b.createPersonalNote(issuer,"礼包币",NoteRegime.FLOAT,"diamond",BigInteger.ONE).success());assertTrue(b.issuePersonalNoteUnbacked(issuer,BigInteger.TEN).success());b.deposit(issuer,"diamond",BigInteger.TEN);ok(b.depositPersonalReserveExact(issuer,BigDecimal.TEN));var coin=b.personalNote(issuer).id();ok(b.configureWelcomeGift(true,0,true,"personal:"+coin,d("0.1234")));assertFalse(b.claimWelcomeGift(p,1).success());assertFalse(claimed(b,p));b.creditUnbacked(issuer,"note",BigInteger.valueOf(1000));var inventory=b.personalHoldingExact(coin,issuer);var reserve=b.effectiveBackingExact(b.personalNote(issuer));ok(b.claimWelcomeGift(p,1));eq("0.1234",b.personalHoldingExact(coin,p));assertEquals(0,inventory.subtract(d("0.1234")).compareTo(b.personalHoldingExact(coin,issuer)));assertEquals(0,reserve.compareTo(b.effectiveBackingExact(b.personalNote(issuer))));assertTrue(b.balanceExact(issuer,"note").signum()>0);assertTrue(claimed(b,p));}
 @Test void snapshotHidesChoicesFromOrdinaryPlayers(){var b=books();var p=UUID.randomUUID();assertFalse(b.welcomeGift(p,false).has("currencies"));assertTrue(b.welcomeGift(p,true).getAsJsonArray("currencies").size()>=3);}
 @Test void simultaneousRequestsSerializeWithoutOverspending(){var b=books();var p=UUID.randomUUID();var q=UUID.randomUUID();b.creditUnbacked(p,"note",BigInteger.ONE);ok(b.configureWelcomeGift(true,0,true,"note",BigDecimal.ONE));ok(b.claimWelcomeGift(p,1));assertEquals("insufficient_treasury",b.claimWelcomeGift(q,1).code());assertFalse(claimed(b,q));eq("0",b.treasuryExact("note"));eq("0",b.balanceExact(q,"note"));}
 @Test void commodityGiftMovesOnlyTreasuryAndKeepsReserve(){var b=books();var admin=UUID.randomUUID();var p=UUID.randomUUID();b.deposit(admin,"copper",BigInteger.TEN);ok(b.transferTreasury(admin,"copper",BigDecimal.TEN,true));var reserve=b.supply("copper").reserveExact();ok(b.configureWelcomeGift(true,0,true,"copper",d("3")));ok(b.claimWelcomeGift(p,1));eq("3",b.balanceExact(p,"copper"));eq("7",b.treasuryExact("copper"));assertEquals(reserve,b.supply("copper").reserveExact());}
}
